/**
 * Fast search through districts by query (matches district or province name in Thai/English)
 */
export function searchDistricts(query: string, limit = 20): ThailandDistrict[] {
    if (!query || query.trim().length === 0) return [];
    const q = query.trim().toLowerCase();

    // Remove common prefixes if typed
    const cleanQ = q.replace(/^(อำเภอ|อ.|เขต)/g, '').trim();

    const matches: { district: ThailandDistrict; score: number }[] = [];

    for (const d of THAILAND_DISTRICTS) {
        const dName = d.name.toLowerCase();
        const dNameEn = d.nameEn.toLowerCase();
        const pName = d.province.toLowerCase();
        const pNameEn = d.provinceEn.toLowerCase();

        let score = 0;

        // Exact match district name
        if (dName === q || dName === cleanQ || dNameEn === q) {
            score = 100;
        } else if (dName.startsWith(cleanQ) || dNameEn.startsWith(q)) {
            score = 80;
        } else if (dName.includes(cleanQ) || dNameEn.includes(q)) {
            score = 60;
        } else if (pName === q || pNameEn === q) {
            score = 40;
        } else if (pName.includes(cleanQ) || pNameEn.includes(q)) {
            score = 20;
        }

        if (score > 0) {
            matches.push({ district: d, score });
        }
    }

    matches.sort((a, b) => b.score - a.score);
    return matches.slice(0, limit).map(m => m.district);
}

/**
 * Get all districts belonging to a specific province
 */
export function getDistrictsByProvince(provinceName: string): ThailandDistrict[] {
    if (!provinceName) return [];
    const cleanProv = provinceName.replace(/^(จังหวัด|จ\s*\.)/g, '').trim();
    return THAILAND_DISTRICTS.filter(d => 
        d.province === provinceName || 
        d.province === cleanProv ||
        d.provinceEn.toLowerCase() === provinceName.toLowerCase().trim()
    );
}
